const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(
    new Cesium.OpenStreetMapImageryProvider({
      url: 'https://tile.openstreetmap.org/',
      maximumLevel: 18,
    })
  ),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

// Eiffel Tower base — Paris sits at ~35 m elevation
const towerBase = Cesium.Cartesian3.fromDegrees(2.2945, 48.8584, 35.0);

// heading 0  → camera faces north  → camera is positioned south of the tower
// pitch -25° → looking slightly down; at range 2400 m the camera sits ~1050 m altitude
//              (35 + 2400 × sin(25°) ≈ 1048 m)
viewer.camera.lookAt(
  towerBase,
  new Cesium.HeadingPitchRange(
    Cesium.Math.toRadians(0.0),   // north-facing: camera is due south
    Cesium.Math.toRadians(-25.0), // look 25° down into the tower
    2400.0,                        // metres from target → ~1050 m altitude
  ),
);
```

The camera is locked south of the Eiffel Tower at roughly **1050 m altitude**, facing due north:

- **Heading 0** places the camera directly south so the tower, Seine, and Trocadéro gardens beyond it are all aligned along the view axis.
- **Pitch −25°** shows the tower with enough ground context to see the river and Champ de Mars foreground.
- **Range 2400 m** from the base keeps the tower well-framed without cropping the plaza.

